// Chat AI - frontend, 5 Nov 2026: AICHAT-1317 batch (push 16:30 UTC, aichat-frontend PR #938 to develop). Tags (merge_tags) + description ONLY where empty. Never replaces text.
const DESCS = {
  '974239744': 'Subtitle under the "Auto" option in the aspect ratio picker of the image composer (on /images and in the chat\'s image mode; dropdown on desktop, bottom sheet on mobile). "Auto" only appears when a photo is attached: the app then keeps the attached photo\'s shape for the edited image instead of a fixed 1:1, 9:16 or 16:9. Noun phrase describing the option, not a button or instruction: "ratio" = the image aspect ratio (width:height), "smart" = picked automatically. Keep it short (one line under the option label). Context: AICHAT-1317.',
  '974239745': 'Heading of the aspect ratio picker in the image composer (on /images and in the chat\'s image mode; dropdown on desktop, bottom sheet on mobile); the same text is the screen-reader label of the ratio button that opens it. Options below it: Auto (only with an attached photo), 1:1, 9:16, 16:9. "Select" is an imperative verb (choose the ratio), not "Selected"; "ratio" = the image aspect ratio (width:height), not a numeric or financial ratio. Keep it short. Context: AICHAT-1317.'
};
const ONLY = [];
return [{ json: { project_id: '691331356a3b9a68428ab3.43540470', tags: ['AICHAT-1317', 'AICHAT-1302', 'image-generation'], descs: DESCS, key_ids: ONLY.length ? ONLY : Object.keys(DESCS) } }];

// Guards: skip archived; tags with merge_tags (only missing ones); description written ONLY when empty. Never replaces text.
const p = $('Params').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const out = []; const skipped = []; const before = []; const expected = {};
for (const id of p.key_ids) {
  const k = byId[id]; if (!k || k.is_archived) { skipped.push({ id: id, why: 'missing/archived' }); continue; }
  before.push({ id: k.key_id, description: k.description || '', tags: k.tags });
  const cur = String(k.description || '').trim();
  const missing = p.tags.filter(function (t) { return (k.tags || []).indexOf(t) === -1; });
  const item = { key_id: Number(id) };
  if (missing.length) { item.tags = missing; item.merge_tags = true; }
  if (!cur) { item.description = p.descs[id]; } else { skipped.push({ id: id, why: 'description not empty – kept' }); }
  expected[id] = item.description || cur;
  if (item.tags || item.description) { out.push(item); }
}
if (out.length === 0) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, before: before, expected: expected, plan: out.map(function (x) { return x.key_id; }) } }];

const p = $('Params').first().json; const B = $('Build').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const oldTags = {}; for (const b of B.before) { oldTags[b.id] = b.tags || []; }
const res = B.plan.map(function (id) { const k = byId[id] || {}; const tags = k.tags || []; const keptOld = (oldTags[id] || []).every(function (t) { return tags.indexOf(t) !== -1; }); const hasNew = p.tags.every(function (t) { return tags.indexOf(t) !== -1; }); return { id: id, ok: k.description === B.expected[String(id)] && hasNew && keptOld, description: k.description, tags: tags }; });
const bad = res.filter(function (x) { return !x.ok; });
return [{ json: { ok: bad.length === 0, results: res, skipped: B.skipped, bad: bad } }];

// Lokalise returned 500 on a 40-key PUT: send 10 keys per call.
const out = [];
for (const it of $input.all()) { const ks = it.json.body.keys; for (let i = 0; i < ks.length; i += 10) { out.push({ json: { body: { keys: ks.slice(i, i + 10) } } }); } }
return out;
